def _parse_value(raw: str) -> object:
    """Parse a profile value into a Python object.

    Accepts literals, containers, and numeric arithmetic (``8 * 1024``); rejects anything
    that could execute code, such as names, calls, or attributes.
    """
    if not raw:
        raise ValueError("empty value")
    return _eval_node(ast.parse(raw, mode="eval").body)


def _load_plugin(name: object):
    """Resolve a built-in transform plugin by name.

    Only names registered in ``plugins.BUILTIN_PLUGINS`` are accepted, so a profile can
    never cause an arbitrary module to be imported and executed.
    """
    if not isinstance(name, str) or name not in BUILTIN_PLUGINS:
